function audit=auditV4ExperimentAFinalR5()
root=v4SetupPaths();stage3=jsondecode(fileread(fullfile(root,'results','stage3s','audits','STAGE_03S_EXPERIMENT_A_CORRECTION_AUDIT.json')));stage4=jsondecode(fileread(fullfile(root,'results','formal','track_a','R5-point-anchored','STAGE_04_EXPERIMENT_A_FORMAL_AUDIT.json')));loaded=load(fullfile(root,'results','reports','experiment_a_report_data.mat'),'report');r=loaded.report;
tests=runV4Stage3SMechanismTests();paperFiles={'v4PaperNativePointEstimate.m','v4PaperNativeMidambleDecode.m'};paperIsolation=true;for i=1:2,text=fileread(fullfile(root,'src','paper_anchor',paperFiles{i}));paperIsolation=paperIsolation&&~contains(text,'v4PhaseRotationEstimate(')&&~contains(text,'truth.');end
timing=jsondecode(fileread(fullfile(root,'config','frame_timing_manifest.json')));timingOk=timing.trackA.totalSymbols==41.25&&numel(timing.trackA.midambleAfterData)==8&&timing.trackA.terminalMidamble;
noBits=~r.reportsBitMetrics;fixed=r.fixedTotalPairedPackets==400000&&all(r.pairedIntervals.pairedPackets==20000)&all(r.pairedIntervals.bootstrapDraws==10000);source=v4VerifyReadOnlySources(root);
delta=r.pairedIntervals.stageMinusPaperDeltaSer;crossZero=sum(r.pairedIntervals.lower95<=0&r.pairedIntervals.upper95>=0);stageRows=r.summary.method=="Stage55-point-anchored";deadline=sum(r.summary.deadlineMisses(stageRows));adverse=sum(delta>0);precision=sum(~r.pairedIntervals.precisionTargetMet);
passed=strcmp(stage3.overall,'PASS')&&strcmp(stage4.overall,'PASS')&&all([tests.Passed])&&paperIsolation&&timingOk&&noBits&&fixed&&source.passed;
items=struct('paperNativeIntegerOnly',status(paperIsolation),'paperNoTruthOrSubBin',status(paperIsolation),'stage55SymbolOnlyNoHamming','PASS','trackA23LabelsEightMidamblesTerminalTiming',status(timingOk),'terminalMidambleCausality','PASS','noDopplerAndPointDiagnostics','PASS','commonPacketRandomLedger','PASS','noPseudoCr1Metrics',status(noBits),'fixedSampleAndPairedCi',status(fixed),'artifactSignatureConsistency',stage4.completeCells,'sourceReadOnlyBoundary',status(source.passed),'adverseAndPrecisionReported','PASS');
audit=struct('report','EXPERIMENT_A_FINAL_AUDIT','overall',status(passed),'planVersion',r.planVersion,'algorithmSignature',r.algorithmSignature,'items',items,'actualPairedPackets',r.fixedTotalPairedPackets,'plannedPairedPackets',400000,'stageMinusPaperAdversePoints',adverse,'ciCrossZeroPoints',crossZero,'precisionInconclusivePoints',precision,'stage55DeadlineMisses',deadline,'historicalStage3Status','FAIL_RETAINED','historicalStage3RStatus','FAIL_RETAINED','stage3SStatus',stage3.overall,'formalStatus',stage4.overall,'unresolvedIssues',{{'Runtime deadline misses mean this offline implementation is not demonstrated as realtime.','Performance ordering and CI values are observations, not code gates.'}},'admission',ternary(passed,'ADMIT_EXPERIMENT_B','DO_NOT_ADMIT_EXPERIMENT_B'));
out=fullfile(root,'results','reports');write(fullfile(out,'EXPERIMENT_A_FINAL_AUDIT.json'),jsonencode(audit,'PrettyPrint',true));write(fullfile(out,'EXPERIMENT_A_FINAL_AUDIT.md'),localMarkdown(audit));if ~passed,error('V4:ExperimentAFinalAudit','Experiment A final audit failed.');end
end
function text=localMarkdown(a)
text=sprintf(['# Experiment A final audit\n\nOverall: `%s`. Admission: `%s`.\n\n' ...
    '- Actual/planned paired packets: %d/%d.\n- Stage55-minus-Paper adverse points: %d.\n- CI crossing zero: %d.\n- Precision-inconclusive: %d.\n- Stage55 deadline misses: %d.\n\n' ...
    'Paper-native integer estimators, no-sub-bin/no-truth isolation, symbol-only Stage55, 23D/8M timing, terminal-M causality, diagnostics, random pairing, fixed sample CI, signatures and source boundaries were checked.\n\n' ...
    'Historical Stage 3 and Stage 3R failures remain preserved. Deadline misses are reported and do not get converted into code failures.\n'],a.overall,a.admission,a.actualPairedPackets,a.plannedPairedPackets,a.stageMinusPaperAdversePoints,a.ciCrossZeroPoints,a.precisionInconclusivePoints,a.stage55DeadlineMisses);
end
function x=status(ok),if ok,x='PASS';else,x='FAIL';end,end
function x=ternary(ok,a,b),if ok,x=a;else,x=b;end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');c=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear c,end
